/**
 * Free AI Chat Widget — no API key, no signup, no cost.
 * ---------------------------------------------------------------
 * Drop this file next to your website's HTML, then add:
 *     <script src="chatbot-widget.js"></script>
 * right before the closing </body> tag of your page.
 *
 * It injects a floating chat bubble (bottom-right corner) that
 * opens a chat window. Responses are generated by simple keyword
 * matching — fast, free, and works completely offline once loaded.
 *
 * TO CUSTOMIZE:
 *   - Edit BOT_NAME, WELCOME_MESSAGE below
 *   - Edit the `rules` array to teach it about YOUR business
 *     (add more entries — the more specific, the smarter it feels)
 * ---------------------------------------------------------------
 */
(function () {
  const BOT_NAME = "Assistant";
  const WELCOME_MESSAGE = "Hi! 👋 How can I help you today?";
  const BRAND_COLOR = "#ff6b35";

  // ---- Teach the bot about your business here ----
  // Each rule: { keywords: [...], response: "..." }
  // The bot checks the visitor's message for any of these keywords
  // (case-insensitive) and replies with the matching response.
  const rules = [
    {
      keywords: ["hello", "hi", "hey", "good morning", "good evening"],
      response: "Hello! Welcome. What can I help you with — products, pricing, or contact info?",
    },
    {
      keywords: ["price", "pricing", "cost", "how much"],
      response: "For pricing details, please check our Pricing page, or tell me which product/service you're interested in.",
    },
    {
      keywords: ["contact", "phone", "email", "reach you", "call"],
      response: "You can reach us via the Contact page, or leave your email here and we'll get back to you!",
    },
    {
      keywords: ["hours", "open", "closing", "timing"],
      response: "Our business hours are Monday–Saturday, 9 AM–7 PM. We're closed on Sundays.",
    },
    {
      keywords: ["delivery", "shipping", "ship"],
      response: "We offer delivery within the city. Delivery time is usually 2–4 business days.",
    },
    {
      keywords: ["return", "refund", "exchange"],
      response: "We accept returns within 7 days of delivery, provided the item is unused and in original packaging.",
    },
    {
      keywords: ["thank", "thanks"],
      response: "You're very welcome! Anything else I can help with?",
    },
    {
      keywords: ["bye", "goodbye", "see you"],
      response: "Thanks for stopping by! Have a great day. 👋",
    },
    {
      keywords: ["human", "agent", "real person", "talk to someone"],
      response: "I can pass you to our team! Please share your phone number or email and someone will contact you shortly.",
    },
  ];

  const FALLBACK_RESPONSES = [
    "That's a great question! Could you tell me a bit more, or ask about our products, pricing, or contact info?",
    "I'm not totally sure about that — but I can help with product info, pricing, delivery, or connecting you to our team.",
    "Hmm, I don't have an exact answer for that. Want me to connect you with a real person?",
  ];

  function getBotResponse(message) {
    const msg = message.toLowerCase();
    for (const rule of rules) {
      if (rule.keywords.some((k) => msg.includes(k))) {
        return rule.response;
      }
    }
    return FALLBACK_RESPONSES[Math.floor(Math.random() * FALLBACK_RESPONSES.length)];
  }

  // ---------------- UI injection ----------------
  const style = document.createElement("style");
  style.textContent = `
    #cw-bubble {
      position: fixed; bottom: 20px; right: 20px;
      width: 60px; height: 60px; border-radius: 50%;
      background: ${BRAND_COLOR}; color: #fff;
      display: flex; align-items: center; justify-content: center;
      font-size: 28px; cursor: pointer; box-shadow: 0 4px 14px rgba(0,0,0,0.25);
      z-index: 999998; transition: transform 0.2s;
      font-family: Arial, sans-serif; border: none;
    }
    #cw-bubble:hover { transform: scale(1.08); }
    #cw-window {
      position: fixed; bottom: 90px; right: 20px;
      width: 320px; max-width: 90vw; height: 420px; max-height: 70vh;
      background: #fff; border-radius: 16px; box-shadow: 0 10px 40px rgba(0,0,0,0.25);
      display: none; flex-direction: column; overflow: hidden;
      font-family: Arial, sans-serif; z-index: 999999;
    }
    #cw-window.open { display: flex; }
    #cw-header {
      background: ${BRAND_COLOR}; color: #fff; padding: 14px 16px;
      font-weight: bold; display: flex; justify-content: space-between; align-items: center;
    }
    #cw-close { cursor: pointer; font-size: 18px; background: none; border: none; color: #fff; }
    #cw-messages {
      flex: 1; overflow-y: auto; padding: 12px; background: #f7f7f9;
      display: flex; flex-direction: column; gap: 8px;
    }
    .cw-msg { max-width: 80%; padding: 8px 12px; border-radius: 12px; font-size: 0.85rem; line-height: 1.4; }
    .cw-msg.bot { background: #fff; border: 1px solid #e5e5e5; align-self: flex-start; }
    .cw-msg.user { background: ${BRAND_COLOR}; color: #fff; align-self: flex-end; }
    #cw-input-row { display: flex; border-top: 1px solid #eee; }
    #cw-input {
      flex: 1; border: none; padding: 12px; font-size: 0.85rem; outline: none;
    }
    #cw-send { background: ${BRAND_COLOR}; color: #fff; border: none; padding: 0 16px; cursor: pointer; font-weight: bold; }
  `;
  document.head.appendChild(style);

  const bubble = document.createElement("button");
  bubble.id = "cw-bubble";
  bubble.innerHTML = "💬";
  document.body.appendChild(bubble);

  const win = document.createElement("div");
  win.id = "cw-window";
  win.innerHTML = `
    <div id="cw-header">
      <span>${BOT_NAME}</span>
      <button id="cw-close">✕</button>
    </div>
    <div id="cw-messages"></div>
    <div id="cw-input-row">
      <input id="cw-input" type="text" placeholder="Type a message..." />
      <button id="cw-send">Send</button>
    </div>
  `;
  document.body.appendChild(win);

  const messagesEl = win.querySelector("#cw-messages");
  const inputEl = win.querySelector("#cw-input");

  function addMessage(text, sender) {
    const div = document.createElement("div");
    div.className = `cw-msg ${sender}`;
    div.textContent = text;
    messagesEl.appendChild(div);
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }

  let opened = false;
  bubble.addEventListener("click", () => {
    opened = !opened;
    win.classList.toggle("open", opened);
    if (opened && messagesEl.children.length === 0) {
      addMessage(WELCOME_MESSAGE, "bot");
    }
  });

  win.querySelector("#cw-close").addEventListener("click", () => {
    opened = false;
    win.classList.remove("open");
  });

  function sendMessage() {
    const text = inputEl.value.trim();
    if (!text) return;
    addMessage(text, "user");
    inputEl.value = "";
    setTimeout(() => {
      addMessage(getBotResponse(text), "bot");
    }, 400);
  }

  win.querySelector("#cw-send").addEventListener("click", sendMessage);
  inputEl.addEventListener("keydown", (e) => {
    if (e.key === "Enter") sendMessage();
  });
})();
